// lib/orte-lage.ts — ERZEUGT, nicht von Hand ändern.
// Quelle: Zensus 2022, Regionaltabellen Demografie und Haushalte (Statistische Ämter des
// Bundes und der Länder). Erzeugt von seo-reports/baue_orte_lage.py aus zensus_orte.json.
//
// ab75                 Menschen ab 75 Jahren im Ort.
// anteil75             dieselbe Zahl als Anteil der Einwohner, in Prozent.
// nurSeniorenAnteil    Anteil der privaten Haushalte, in denen ausschliesslich Seniorinnen
//                      und Senioren leben. Amtlich ist Senior, wer das 65. Lebensjahr
//                      vollendet hat (Methodikblatt der Regionaltabelle Haushalte).
// nurSeniorenHaushalte dieselbe Groesse als Anzahl, auf Hunderter gerundet — die Quote hat
//                      nur eine Nachkommastelle, alles Genauere waere Scheingenauigkeit.
//
// Bundeswerte zum Vergleich: 9.163.427 Menschen ab 75 (11.1 % der Einwohner),
// 24.6 % der Haushalte nur mit Seniorinnen und Senioren.

export interface Wohnen {
  /** Durchschnittliche Wohnflaeche je Wohnung, m2. */
  flaeche?: number
  /** Anteil der Wohnungen unter 60 m2, Prozent. */
  unter60?: number
  /** Anteil der Haushalte, die im Eigentum wohnen, Prozent. */
  eigentum?: number
  /** Bestandsmiete der vermieteten Wohnungen, EUR je m2 nettokalt. */
  qmmiete?: number
  /** Wohnungen je Gebaeude. */
  whg_je_gebaeude?: number
  /** Anteil der Gebaeude mit hoechstens zwei Wohnungen, Prozent. */
  efh_zfh_anteil?: number
  /** Anteil der Gebaeude, die freistehen, Prozent. */
  freistehend?: number
  /** Anteil der Gebaeude in geschlossener Reihe (beidseitig angebaut), Prozent. */
  reihenhaus?: number
  /** Anteil der Wohnungen aus der Zeit vor 1970, Prozent. */
  vor1970?: number
}

export interface OrtLage {
  ort: string
  land: string
  ab75: number
  anteil75: number
  nurSeniorenAnteil: number
  nurSeniorenHaushalte: number
  wohnen: Wohnen
  /** Dieselben Groessen fuer das Bundesland — bei Stadtstaaten der Bund. */
  landWohnen: Pick<Wohnen, 'flaeche' | 'unter60' | 'eigentum' | 'whg_je_gebaeude'>
}

